"""
نظام تدقيق البيانات الحكومية — Government Data Auditing System
================================================================
Backend  : FastAPI + Pandas + Ollama (Local AI)
Features : CSV/Excel auditing, configurable Ollama endpoint,
           bilingual (Arabic/English) AI analysis, dashboard data.
"""

from fastapi import FastAPI, UploadFile, File, Body
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, JSONResponse
import pandas as pd
import io
import os
import re
import json
import requests

# ---------------------------------------------------------------------------
# Paths & configuration
# ---------------------------------------------------------------------------
BASE_DIR = os.path.dirname(os.path.abspath(__file__))
INDEX_PATH = os.path.join(BASE_DIR, "index.html")
CONFIG_PATH = os.path.join(BASE_DIR, "config.json")

DEFAULT_CONFIG = {
    "ollama_url": "http://127.0.0.1:11434",  # can point to any machine/device
    "model": "qwen3:4b",
    "language": "ar",              # ar | en
    "max_ai_records": 40,          # max anomalies per rule sent to the model
    "temperature": 0.2,
    "request_timeout": 300,        # seconds — local models can be slow
}


def load_config() -> dict:
    """Read config.json (falling back to defaults for missing keys)."""
    cfg = dict(DEFAULT_CONFIG)
    try:
        with open(CONFIG_PATH, "r", encoding="utf-8") as fh:
            cfg.update(json.load(fh))
    except Exception:
        pass
    return cfg


def save_config(new: dict) -> dict:
    """Persist only known keys so the file stays clean."""
    cfg = load_config()
    for key in DEFAULT_CONFIG:
        if isinstance(new, dict) and new.get(key) is not None:
            cfg[key] = new[key]
    with open(CONFIG_PATH, "w", encoding="utf-8") as fh:
        json.dump(cfg, fh, ensure_ascii=False, indent=2)
    return cfg


# ---------------------------------------------------------------------------
# App
# ---------------------------------------------------------------------------
app = FastAPI(title="نظام تدقيق البيانات الحكومية", version="2.0")

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


# ---------------------------------------------------------------------------
# Static frontend
# ---------------------------------------------------------------------------
@app.get("/", include_in_schema=False)
def index():
    if os.path.exists(INDEX_PATH):
        return FileResponse(INDEX_PATH)
    return JSONResponse({"error": "index.html not found"}, status_code=404)


@app.get("/health")
def health():
    return {"status": "ok", "service": "government-audit", "version": "2.0"}


# ---------------------------------------------------------------------------
# Settings (Ollama endpoint is fully configurable -> portable between devices)
# ---------------------------------------------------------------------------
@app.get("/settings")
def get_settings():
    return load_config()


@app.post("/settings")
def update_settings(payload: dict = Body(...)):
    return save_config(payload)


# ---------------------------------------------------------------------------
# Ollama helpers
# ---------------------------------------------------------------------------
@app.get("/ollama/models")
def ollama_models(url: str | None = None):
    """List models available on the configured (or overridden) Ollama server."""
    base = (url or load_config().get("ollama_url") or "").rstrip("/")
    if not base:
        return {"ok": False, "models": [], "error": "no_url"}
    try:
        resp = requests.get(f"{base}/api/tags", timeout=8)
        resp.raise_for_status()
        models = [m.get("name") for m in resp.json().get("models", []) if m.get("name")]
        return {"ok": True, "url": base, "models": sorted(models), "count": len(models)}
    except Exception as exc:  # noqa: BLE001 - surface any connection problem to UI
        return {"ok": False, "url": base, "models": [], "error": str(exc)}


def _strip_think(text: str) -> str:
    """Remove qwen3-style  thinking...<｜end▁of▁thinking｜> reasoning blocks from output."""
    return re.sub(r"(?is) thinking.*?<｜end▁of▁thinking｜>", "", text or "").strip()


def call_ollama(messages: list, model: str, url: str, cfg: dict) -> str:
    base = (url or "").rstrip("/")
    if not base:
        raise ValueError("no_url")
    body = {
        "model": model,
        "messages": messages,
        "stream": False,
        "options": {"temperature": float(cfg.get("temperature", 0.2))},
    }
    resp = requests.post(
        f"{base}/api/chat",
        json=body,
        timeout=int(cfg.get("request_timeout", 300)),
    )
    resp.raise_for_status()
    data = resp.json()
    content = (data.get("message") or {}).get("content", "")
    return _strip_think(content)


def _prompt_messages(lang: str, digest: str) -> list:
    if lang == "en":
        system = (
            "You are an expert government financial auditor specialised in fraud "
            "and anomaly detection. Analyse the audit findings and reply ONLY in "
            "English. Use clear Markdown with these sections: "
            "## Executive summary, ## Key findings, ## Risk level (Low/Medium/High), "
            "## Recommendations. Be concise, specific and actionable."
        )
        user = f"Audit findings to analyse:\n\n{digest}"
    else:
        system = (
            "أنت مدقق مالي حكومي خبير متخصص في كشف الاحتيال والشذوذ في البيانات. "
            "حلّل نتائج التدقيق واكتب ردك باللغة العربية فقط، بتنسيق Markdown واضح "
            "بالأقسام التالية: ## الملخص التنفيذي، ## أبرز الملاحظات، "
            "## درجة الخطورة (منخفضة/متوسطة/عالية)، ## التوصيات. "
            "كن دقيقاً وموجزاً وقدّم توصيات قابلة للتنفيذ."
        )
        user = f"نتائج التدقيق المطلوب تحليلها:\n\n{digest}"
    return [
        {"role": "system", "content": system},
        {"role": "user", "content": user},
    ]


def _build_digest(payload: dict, lang: str, limit: int) -> str:
    summary = payload.get("summary", {}) or {}
    details = payload.get("details", {}) or {}

    def take(rows):
        rows = rows or []
        return rows[:limit]

    digest = {
        "total_records": payload.get("total_records_scanned", 0),
        "summary": summary,
        "duplicate_payments": take(details.get("duplicate_payments")),
        "split_purchases": take(details.get("split_purchases")),
        "weekend_transactions": take(details.get("weekend_transactions")),
    }
    return json.dumps(digest, ensure_ascii=False, indent=2)


