# ---------------------------------------------------------------------------
@app.post("/analyze/")
def analyze(payload: dict = Body(...)):
    cfg = load_config()
    lang = "en" if str(payload.get("language", cfg.get("language", "ar"))).lower().startswith("en") else "ar"
    model = payload.get("model") or cfg.get("model")
    url = payload.get("ollama_url") or cfg.get("ollama_url")

    if not model:
        return {"ok": False, "error": "no_model"}
    if not url:
        return {"ok": False, "error": "no_url"}

    digest = _build_digest(payload, lang, int(cfg.get("max_ai_records", 40)))
    messages = _prompt_messages(lang, digest)

    try:
        analysis = call_ollama(messages, model, url, cfg)
    except requests.exceptions.ConnectTimeout:
        return {"ok": False, "error": "timeout", "detail": url}
    except requests.exceptions.ConnectionError:
        return {"ok": False, "error": "connection", "detail": url}
    except requests.exceptions.HTTPError as exc:
        return {"ok": False, "error": "http", "detail": str(exc)}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "error": "unknown", "detail": str(exc)}

    if not analysis:
        return {"ok": False, "error": "empty_response", "model": model}

    return {"ok": True, "analysis": analysis, "model": model, "language": lang}


# ---------------------------------------------------------------------------
# Auditing engine (rules)
# ---------------------------------------------------------------------------
def _read_dataframe(filename: str, contents: bytes) -> pd.DataFrame:
    name = (filename or "").lower()
    if name.endswith(".csv"):
        return pd.read_csv(io.BytesIO(contents))
    if name.endswith((".xlsx", ".xlsm", ".xls")):
        return pd.read_excel(io.BytesIO(contents))
    raise ValueError("unsupported_format")


def run_audit(df: pd.DataFrame) -> dict:
    """Apply the three detection rules and return a JSON-ready report."""
    df = df.copy()
    df.columns = [str(c).strip() for c in df.columns]

    missing = [c for c in ["date", "vendor_id", "amount"] if c not in df.columns]
    if missing:
        raise ValueError("missing_columns:" + ",".join(missing))

    df["date"] = pd.to_datetime(df["date"], errors="coerce")
    df["amount"] = pd.to_numeric(df["amount"], errors="coerce")
    df = df.dropna(subset=["date", "amount"])

    # duplicate_payments: same vendor + same amount --------------------------
    duplicates = df[df.duplicated(subset=["vendor_id", "amount"], keep=False)].copy()
    duplicates = duplicates.sort_values(["vendor_id", "amount", "date"])
    duplicates["date"] = duplicates["date"].dt.strftime("%Y-%m-%d")

    # split_purchases: vendor weekly total > 10,000 --------------------------
    # W-SUN = calendar week starting Monday and ending Sunday.
    weekly = (
        df.groupby(["vendor_id", pd.Grouper(key="date", freq="W-SUN", label="left", closed="left")])["amount"]
        .sum()
        .reset_index()
    )
    split_purchases = weekly[weekly["amount"] > 10000].copy()
    split_purchases = split_purchases.sort_values("amount", ascending=False)
    split_purchases["date"] = split_purchases["date"].dt.strftime("%Y-%m-%d")

    # weekend_transactions: Friday (4) & Saturday (5) ------------------------
    df["day_of_week"] = df["date"].dt.dayofweek
    weekend = df[df["day_of_week"].isin([4, 5])].copy()
    weekend = weekend.drop(columns=["day_of_week"])
    weekend["date"] = weekend["date"].dt.strftime("%Y-%m-%d")

    columns = [c for c in ["transaction_id", "date", "vendor_id", "amount",
                           "invoice_number", "description"] if c in df.columns]
    columns = ["vendor_id", "date", "amount"] if not columns else columns

    total = int(len(df))
    dup_n, split_n, wk_n = len(duplicates), len(split_purchases), len(weekend)
    # Weighted risk score (0-100)
    risk = min(100, round(((dup_n * 2 + split_n * 3 + wk_n) / max(total, 1)) * 100))

    return {
        "total_records_scanned": total,
        "risk_score": risk,
        "summary": {
            "duplicate_payments_count": dup_n,
            "split_purchases_suspects": split_n,
            "weekend_transactions_count": wk_n,
        },
        "details": {
            "duplicate_payments": duplicates[columns].to_dict(orient="records"),
            "split_purchases": split_purchases.rename(columns={"date": "week"}).to_dict(orient="records"),
            "weekend_transactions": weekend[columns].to_dict(orient="records"),
        },
    }


@app.post("/audit/")
async def audit_data(file: UploadFile = File(...)):
    contents = await file.read()
    try:
        df = _read_dataframe(file.filename, contents)
    except ValueError as exc:
        if str(exc) == "unsupported_format":
            return {"error": "unsupported_format"}
        raise
    except Exception as exc:  # noqa: BLE001 - e.g. corrupted Excel / missing engine
        return {"error": "read_failed", "detail": str(exc)}

    try:
        report = run_audit(df)
    except ValueError as exc:
        msg = str(exc)
        if msg.startswith("missing_columns:"):
            return {"error": "missing_columns", "columns": msg.split(":", 1)[1].split(",")}
        raise

    report["filename"] = file.filename
    return report


