def call_ollama(messages: list, model: str, url: str, cfg: dict) -> str:
    base = (url or "").rstrip("/")
    if not base:
        raise ValueError("no_url")
    body = {
        "model": model,
        "messages": messages,
        "stream": False,
        "options": {"temperature": float(cfg.get("temperature", 0.2))},
    }
    resp = requests.post(
        f"{base}/api/chat",
        json=body,
        timeout=int(cfg.get("request_timeout", 300)),
    )
    resp.raise_for_status()
    data = resp.json()
    content = (data.get("message") or {}).get("content", "")
    return _strip_think(content)

