const tabID = "tab_d6a5f5d7-2ab7-441b-8015-7897becec6e3";
const r = await tools.browser.evaluate({
  tabID,
  script: `(function(){
    const results = {};
    // 1) any network resource from outside our own server?
    results.externalResources = performance.getEntriesByType('resource')
      .map(e => e.name).filter(n => n.startsWith('http') && !n.startsWith(location.origin));
    // 2) any <link>/<script>/<img> pointing to the web?
    results.externalTags = [...document.querySelectorAll('link[href],script[src],img[src]')]
      .map(el => el.href || el.src).filter(u => u.startsWith('http') && !u.startsWith(location.origin));
    // 3) chart actually renders locally
    const cv = document.createElement('canvas'); cv.width = 200; cv.height = 100;
    document.body.appendChild(cv);
    const ch = new Chart(cv.getContext('2d'), { type: 'bar', data: { labels: ['أ','ب'], datasets: [{ data: [3, 7] }] }, options: { animation: false } });
    const pixels = cv.getContext('2d').getImageData(0, 0, 200, 100).data;
    let colored = 0;
    for (let i = 3; i < pixels.length; i += 4) if (pixels[i] > 0) colored++;
    ch.destroy(); cv.remove();
    results.chartPaintedPixels = colored;
    return JSON.stringify(results);
  })()`
});
return JSON.parse(r.value);

